export const priorityWebsiteCityPages = websiteCityPages.filter((cityPage) => cityPage.priority === 'tier_1');

export const getWebsiteCityPath = (cityPage: WebsiteCityPage) => `/${cityPage.slug}/`;

export const getCityAudienceExamples = (cityPage: WebsiteCityPage) => cityPage.audienceExamples.slice(0, 5);

export const getNearbyWebsiteCityPages = (currentCity: WebsiteCityPage, limit = 4) => {
  const sameProvince = websiteCityPages.filter(
    (item) => item.slug !== currentCity.slug && item.province === currentCity.province,
  );

  const priorityFallback = websiteCityPages.filter(
    (item) => item.slug !== currentCity.slug && item.province !== currentCity.province && item.priority === 'tier_1',
  );

  const fallback = websiteCityPages.filter(
    (item) =>
      item.slug !== currentCity.slug &&
      item.province !== currentCity.province &&
      item.priority !== 'tier_1',
  );

  return [...sameProvince, ...priorityFallback, ...fallback].slice(0, limit);
};
